        "shadow-[0_1px_0_rgba(255,255,255,0.9)_inset,0_2px_4px_-1px_rgba(3,18,43,0.08),0_18px_40px_-14px_rgba(3,18,43,0.28),0_50px_90px_-30px_rgba(3,18,43,0.5)]",
