              {t.ct > 1.5 && <span className="ov-num text-[12px] font-semibold text-white">{fmt(t.ct, 1)}</span>}
            </span>
          ))}
        </div>
      </div>

      {/* Im Pool */}
      <div className="mt-5">
        <div className="flex items-baseline justify-between text-[14px]">
          <span className="font-semibold text-ink-800">Im Pool</span>
          <span className="ov-num font-display text-[20px] font-extrabold text-ov-700">
            {fmt(summe - hebelMax, 1)}–{fmt(summe - hebelMin, 1)}
          </span>
        </div>
        <div className="mt-2 flex h-11 overflow-hidden rounded-xl" role="img" aria-label={`Im Pool: Beschaffung um ${fmt(hebelMin, 1)} bis ${fmt(hebelMax, 1)} ct niedriger, feste Bestandteile unverändert`}>
          <span className={cn("flex h-full items-center justify-center", FARBEN.beschaffung)} style={{ width: pct(beschaffung.ct - hebelMax) }}>
            <span className="ov-num text-[12px] font-semibold text-white">Beschaffung</span>
          </span>
          <span className="h-full border-r-2 border-white bg-[repeating-linear-gradient(135deg,#cde3b1_0_6px,#e6f1d8_6px_12px)]" style={{ width: pct(hebelMax - hebelMin) }} />
          {fix.map((t) => (
            <span key={t.id} className={cn("h-full border-r-2 border-white last:border-r-0", FARBEN[t.id])} style={{ width: pct(t.ct) }} />
          ))}
          <span className="flex h-full items-center justify-center bg-sun-100" style={{ width: pct(hebelMin) }}>
            <span className="sr-only">Ersparnis</span>
          </span>
        </div>
        <div className="mt-2 flex flex-wrap items-center gap-x-4 gap-y-1 text-[12px] text-ink-500" aria-hidden="true">
          <span className="inline-flex items-center gap-1.5"><span className="h-2.5 w-2.5 rounded-[3px] bg-[repeating-linear-gradient(135deg,#aed083_0_3px,#e6f1d8_3px_6px)] ring-1 ring-ov-200" />Spanne je nach Profil</span>
          <span className="inline-flex items-center gap-1.5"><span className="h-2.5 w-2.5 rounded-[3px] bg-sun-100 ring-1 ring-sun-200" />mindestens eingespart</span>
          <span className="inline-flex items-center gap-1.5"><span className="h-2.5 w-2.5 rounded-[3px] bg-navy-700" />fest: Netz, Umlagen, Steuer</span>
        </div>
      </div>

      {/* Hebel */}
      <ul className="mt-6 grid gap-2 border-t border-ink-100 pt-5 sm:grid-cols-3">
        {STROM.poolHebel.map((h) => {
          const Icon = HEBEL_ICONS[h.id] || Handshake;
          return (
            <li key={h.id} className="flex items-center gap-3 rounded-xl bg-ov-50/70 px-3 py-2.5 ring-1 ring-inset ring-ov-100 sm:flex-col sm:items-start sm:gap-2">
              <span aria-hidden="true" className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-white text-ov-700 ring-1 ring-ov-200"><Icon className="h-4 w-4" /></span>
              <span className="min-w-0 flex-1">
                <span className="block text-[12.5px] font-semibold leading-snug text-ink-800">{h.label.replace(" im virtuellen Kraftwerk", "").replace(" aus Parks der Gruppe", "")}</span>
                <span className="ov-num block text-[12.5px] font-bold text-ov-700">−{fmt(h.ct.min, 1)} bis −{fmt(h.ct.max, 1)} ct</span>
              </span>
            </li>
          );
        })}
      </ul>
      <p className="mt-4 text-[11.5px] leading-relaxed text-ink-500">Grobe Aufteilung (BDEW-Strompreisanalyse, eigene Einschätzung). Die Pool-Hebel wirken nur auf die Beschaffung, je nach Profil, Menge und Marktlage.</p>
    </figure>
  );
}

